from functools import wraps

def announce(function):
    @wraps(function)
    def wrapper(*args, **kwargs):
        print(f"calling {function.__name__}")
        return function(*args, **kwargs)
    return wrapper

@announce
def add(left, right):
    return left + right

print(add(2, 3))
print(add.__name__)

